		$q = sanitize_text_field( (string) $request->get_param( 'q' ) );
		$species = sanitize_text_field( (string) $request->get_param( 'species' ) );
		if ( mb_strlen( $q ) < 2 ) {
			return rest_ensure_response( array( 'ok' => true, 'products' => array(), 'brands' => array() ) );
		}

		// Rusis -> pa_gyvuno_rusis slug (patikrinta recon 2026-07-15: sunims 1784, katems 809)
		$species_map = array(
			'dog'     => array( 'sunims' ),
			'cat'     => array( 'katems' ),
			'bird'    => array( 'pauksciams' ),
			'rodent'  => array( 'grauzikams' ),
			'fish'    => array( 'zuvims' ),
		);

		$args = array(
			'post_type'      => 'product',
			'post_status'    => 'publish',
			's'              => $q,
			'posts_per_page' => 6,
			'no_found_rows'  => true,
		);
		if ( isset( $species_map[ $species ] ) ) {
			$args['tax_query'] = array( array(
				'taxonomy' => 'pa_gyvuno_rusis',
				'field'    => 'slug',
				'terms'    => $species_map[ $species ],
				'operator' => 'IN',
			) );
		}

		$products = array();
		$wpq = new WP_Query( $args );
		foreach ( $wpq->posts as $post ) {
			$brands = wp_get_object_terms( $post->ID, self::BRAND_TAXONOMY, array( 'fields' => 'names' ) );
			$prod   = function_exists( 'wc_get_product' ) ? wc_get_product( $post->ID ) : null;
			// Pakuote — is pa_pakuotes_dydis (recon: uzpildyta, 72 terminai).
			// Butina, nes "Josera SensiPlus" turi kelis variantus ir refill'ui svarbu KURIS.
			$pak = wp_get_object_terms( $post->ID, 'pa_pakuotes_dydis', array( 'fields' => 'names' ) );
			$products[] = array(
				'id'      => (int) $post->ID,
				'name'    => $post->post_title,
				'brand'   => ( ! is_wp_error( $brands ) && $brands ) ? $brands[0] : '',
				'sku'     => $prod ? (string) $prod->get_sku() : '',
				'package' => ( ! is_wp_error( $pak ) && $pak ) ? $pak[0] : '',
			);
		}

		// Brendai — fallback grupe (max 3)
		$brands_out = array();
		if ( taxonomy_exists( self::BRAND_TAXONOMY ) ) {
			$terms = get_terms( array(
				'taxonomy'   => self::BRAND_TAXONOMY,
				'hide_empty' => true,
				'search'     => $q,
				'number'     => 3,
			) );
			if ( ! is_wp_error( $terms ) ) {
				foreach ( $terms as $t ) {
					$brands_out[] = array( 'name' => $t->name );
				}
			}
		}

		return rest_ensure_response( array( 'ok' => true, 'products' => $products, 'brands' => $brands_out ) );
	}

